WITH filtered AS (SELECT *, CONCAT(browser, '/', device) AS browser_device FROM sessions WHERE customer_id IS NOT NULL), gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at ASC, id ASC) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at ASC, id ASC) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS session_start_flag FROM filtered), sessions_sessions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY country ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT DATE_TRUNC('WEEK', started_at) AS week_start, device, DATE_TRUNC('MONTH', started_at) AS activity_month, SUM(CASE WHEN browser = 'Safari' THEN session_id ELSE 0 END) AS safari_session_id, ROUND(SUM(session_start_flag) / NULLIF(COUNT(CASE WHEN browser = 'Safari' THEN 1 END), 0), 2) AS session_start_flag_per_safari, MAX(session_start_flag) AS max_session_start_flag, GROUPING(DATE_TRUNC('WEEK', started_at)) AS gid FROM sessions_sessions GROUP BY GROUPING SETS ((DATE_TRUNC('WEEK', started_at), device, DATE_TRUNC('MONTH', started_at)), (DATE_TRUNC('WEEK', started_at), device), (DATE_TRUNC('WEEK', started_at)));
